CREATE TABLE public.bo_export_counter (
    id boolean DEFAULT true NOT NULL,
    counter integer DEFAULT 0 NOT NULL
);

CREATE TABLE public.staging_tempo_historico (
    fila bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    concatenate text,
    tempo_id text,
    procesado boolean DEFAULT false NOT NULL
);

CREATE OR REPLACE FUNCTION public.fn_audit_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_operation audit_operation_enum;
begin
    if tg_op = 'INSERT' then
        insert into audit_logs(table_name, row_id, operation, old_data, new_data)
        values (tg_table_name, new.id, 'INSERT', null, to_jsonb(new));
        return new;
    elsif tg_op = 'UPDATE' then
        -- Si lo único que cambió es updated_at, no hay nada que auditar.
        if (to_jsonb(old) - 'updated_at') = (to_jsonb(new) - 'updated_at') then
            return new;
        end if;
        v_operation := case when new.deleted_at is not null and old.deleted_at is null then 'SOFT_DELETE' else 'UPDATE' end;
        insert into audit_logs(table_name, row_id, operation, old_data, new_data)
        values (tg_table_name, new.id, v_operation, to_jsonb(old), to_jsonb(new));
        return new;
    elsif tg_op = 'DELETE' then
        insert into audit_logs(table_name, row_id, operation, old_data, new_data)
        values (tg_table_name, old.id, 'HARD_DELETE', to_jsonb(old), null);
        return old;
    end if;
    return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_carga_historica_tempo_batch(p_rows jsonb)
 RETURNS TABLE(idx integer, estado text, detalle text)
 LANGUAGE plpgsql
AS $function$
declare
    r          jsonb;
    i          integer := 0;
    v_in       text;
    v_tempo    text;
    v_pos      integer;
    v_rpos     integer;
    v_track    text;
    v_artist   text;
    v_id       uuid;
    v_actual   text;
    v_new_num  boolean;
    v_act_num  boolean;
begin
    for r in select * from jsonb_array_elements(p_rows) loop
        i := i + 1;
        begin
            v_in    := regexp_replace(trim(coalesce(r->>'track_artist', '')), '\s+', ' ', 'g');
            v_tempo := nullif(trim(coalesce(r->>'tempo_id', '')), '');

            -- Numéricos sin ceros de relleno; "0" cuenta como vacío.
            if v_tempo ~ '^[0-9]+$' then
                v_tempo := nullif(ltrim(v_tempo, '0'), '');
            end if;

            if v_in = '' then
                idx := i; estado := 'ERROR'; detalle := 'Fila sin título';
                return next; continue;
            end if;
            if v_tempo is null then
                idx := i; estado := 'IGNORADA'; detalle := 'Tempo ID vacío o 0';
                return next; continue;
            end if;

            -- 1) Obra y artista por el último " - ", normalizados.
            v_id := null; v_actual := null;
            v_rpos := position(' - ' in reverse(v_in));
            if v_rpos > 0 then
                v_pos    := length(v_in) - v_rpos - 1;
                v_track  := substring(v_in from 1 for v_pos - 1);
                v_artist := substring(v_in from v_pos + 3);

                select tm.id, tm.tempo_id into v_id, v_actual
                from tracks_master tm
                where tm.deleted_at is null
                  and lower(tm.track_name_clean)  = lower(fn_normalize_text(v_track))
                  and lower(tm.artist_name_clean) = lower(fn_normalize_text(v_artist))
                limit 1;
            end if;

            -- 2) Respaldo: texto completo tal cual.
            if v_id is null then
                select tm.id, tm.tempo_id into v_id, v_actual
                from tracks_master tm
                where tm.deleted_at is null
                  and lower(tm.track_artist_concat) = lower(v_in)
                limit 1;
            end if;

            if v_id is null then
                idx := i; estado := 'NO ENCONTRADA'; detalle := 'No existe en la tabla principal';
                return next; continue;
            end if;

            v_new_num := v_tempo ~ '^[0-9]+$';
            v_act_num := coalesce(v_actual ~ '^[0-9]+$', false);

            if v_actual is not null and fn_norm_tempo_id(v_actual) = fn_norm_tempo_id(v_tempo) then
                idx := i; estado := 'SIN CAMBIOS'; detalle := 'Ya tenía ese tempo_id';

            elsif v_act_num and v_new_num then
                idx := i; estado := 'CONFLICTO';
                detalle := 'Ya tiene ' || v_actual || '; el archivo trae ' || v_tempo || ' (no se pisó)';

            elsif v_act_num and not v_new_num then
                idx := i; estado := 'SIN CAMBIOS';
                detalle := 'Ya tiene el número ' || v_actual || '; se ignora el marcador ' || v_tempo;

            else
                update tracks_master
                set tempo_id  = v_tempo,
                    estado_bo = case when v_new_num then 'ok'::estado_bo_enum else estado_bo end
                where id = v_id;

                if v_new_num then
                    perform fn_merge_tempo_duplicates(v_tempo);
                end if;

                idx := i; estado := 'ACTUALIZADA';
                detalle := 'Antes: ' || coalesce(v_actual, 'vacío');
            end if;
            return next;

        exception when others then
            idx := i; estado := 'ERROR'; detalle := sqlerrm;
            return next;
        end;
    end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_next_bo_carga()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare v_n integer;
begin
    update bo_export_counter set counter = counter + 1 where id = true returning counter into v_n;
    return v_n;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_normalize_text(p_input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
    v_text text;
begin
    if p_input is null then
        return null;
    end if;

    -- Proteger "¿" y "¡" de unaccent (los convierte en "?" y "!").
    v_text := replace(p_input, '¿', chr(1));
    v_text := replace(v_text,  '¡', chr(2));

    v_text := unaccent(v_text);

    v_text := regexp_replace(v_text, '\s*&\s*', ', ', 'g');

    -- (En vivo) / [Live Session] / (Grabado en vivo) ...
    v_text := regexp_replace(v_text, '\s*[\(\[][^\)\]]*\y(en\s+vivo|vivo|live)\y[^\)\]]*[\)\]]\s*', ' ', 'gi');

    -- Segmento entre guiones que arranca con en vivo/live, con o sin
    -- texto extra: "A - En Vivo Gran Rex - B" -> "A - B"
    v_text := regexp_replace(v_text, '\s*-\s*(en\s+vivo|vivo|live)\y[^-]*\s*-\s*', ' - ', 'gi');

    -- Lo mismo al final del título: "A - En Vivo en la Plaza..." -> "A"
    v_text := regexp_replace(v_text, '\s*-\s*(en\s+vivo|vivo|live)\y[^-]*$', '', 'gi');

    v_text := regexp_replace(v_text, '\s+', ' ', 'g');
    v_text := trim(v_text);

    v_text := replace(v_text, chr(1), '¿');
    v_text := replace(v_text, chr(2), '¡');

    return v_text;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_safe_bigint(v text)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
    if v is null or trim(lower(v)) in ('', 'n/a', 'na', '-', 'null') then return null; end if;
    return v::bigint;
exception when others then return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_safe_int(v text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
    if v is null or trim(lower(v)) in ('', 'n/a', 'na', '-', 'null') then return null; end if;
    return v::integer;
exception when others then return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_safe_numeric(v text)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
begin
    if v is null or trim(lower(v)) in ('', 'n/a', 'na', '-', 'null') then return null; end if;
    return v::numeric;
exception when others then return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_set_tempo_id(p_track_id uuid, p_tempo_id text)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare v_clean text := nullif(trim(p_tempo_id), '');
begin
    update tracks_master
    set tempo_id = v_clean,
        estado_bo = case when v_clean is not null then 'ok'::estado_bo_enum else estado_bo end
    where id = p_track_id and deleted_at is null;

    return fn_merge_tempo_duplicates(v_clean);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_upsert_bo_report_batch(p_rows jsonb, p_pais_code pais_code_enum)
 RETURNS TABLE(idx integer, error_message text)
 LANGUAGE plpgsql
AS $function$
declare r jsonb; i integer := 0;
begin
    for r in select * from jsonb_array_elements(p_rows) loop
        i := i + 1;
        begin
            perform fn_upsert_bo_report_row(
                r->>'tempo_id', p_pais_code, r->>'bo_id', r->>'ca',
                r->>'bo_status', r->>'reclamos', fn_safe_numeric(r->>'mech_bo')
            );
            idx := i; error_message := null;
            return next;
        exception when others then
            idx := i; error_message := sqlerrm;
            return next;
        end;
    end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_upsert_bo_report_row(p_tempo_id text, p_pais_code pais_code_enum, p_bo_id text, p_ca text, p_bo_status text, p_reclamos text, p_mech_bo numeric)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare
    v_master_id uuid;
    v_tempo_id  text;
    v_bo_id     text;
    v_row_id    uuid;
begin
    select tm.id, tm.tempo_id into v_master_id, v_tempo_id
    from tracks_master tm
    where fn_norm_tempo_id(tm.tempo_id) = fn_norm_tempo_id(p_tempo_id)
      and tm.deleted_at is null
    limit 1;

    if v_master_id is null then
        raise exception 'tempo_id % no existe en la tabla principal.', p_tempo_id;
    end if;

    -- BO ID sin ceros de relleno (solo si es numérico).
    v_bo_id := case
        when trim(coalesce(p_bo_id, '')) ~ '^[0-9]+$' then ltrim(trim(p_bo_id), '0')
        else nullif(trim(p_bo_id), '')
    end;

    insert into territory_bo_report (track_master_id, tempo_id, pais_code, bo_id, ca, bo_status, reclamos, mech_bo)
    values (v_master_id, v_tempo_id, p_pais_code, v_bo_id, p_ca, p_bo_status, p_reclamos, p_mech_bo)
    on conflict (tempo_id, pais_code)
    do update set
        bo_id = excluded.bo_id, ca = excluded.ca, bo_status = excluded.bo_status,
        reclamos = excluded.reclamos, mech_bo = excluded.mech_bo,
        deleted_at = null, updated_at = now()
        -- estado_trabajo queda afuera a propósito: no se pisa.
    returning id into v_row_id;

    return v_row_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_upsert_control_batch(p_rows jsonb, p_pais_code pais_code_enum)
 RETURNS TABLE(idx integer, error_message text)
 LANGUAGE plpgsql
AS $function$
declare r jsonb; i integer := 0;
begin
    for r in select * from jsonb_array_elements(p_rows) loop
        i := i + 1;
        begin
            perform fn_upsert_control_row(
                r->>'tempo_id', p_pais_code, fn_safe_numeric(r->>'percent_ctrl'),
                fn_safe_numeric(r->>'collect_mec'), fn_safe_numeric(r->>'collect_ejec'),
                r->>'control', r->>'cwr', r->>'nota'
            );
            idx := i; error_message := null;
            return next;
        exception when others then
            idx := i; error_message := sqlerrm;
            return next;
        end;
    end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_upsert_control_row(p_tempo_id text, p_pais_code pais_code_enum, p_percent_ctrl numeric, p_collect_mec numeric, p_collect_ejec numeric, p_control text, p_cwr text, p_nota text)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare v_master_id uuid; v_row_id uuid;
begin
    select id into v_master_id from tracks_master where tempo_id = p_tempo_id and deleted_at is null;
    if v_master_id is null then
        raise exception 'tempo_id % no existe en la tabla principal. Cargalo ahí primero.', p_tempo_id;
    end if;

    insert into territory_control (track_master_id, tempo_id, pais_code, percent_ctrl, collect_mec, collect_ejec, control, cwr, nota)
    values (v_master_id, p_tempo_id, p_pais_code, p_percent_ctrl, p_collect_mec, p_collect_ejec, p_control, p_cwr, p_nota)
    on conflict (tempo_id, pais_code)
    do update set
        percent_ctrl = excluded.percent_ctrl, collect_mec = excluded.collect_mec, collect_ejec = excluded.collect_ejec,
        control = excluded.control, cwr = excluded.cwr, nota = excluded.nota,
        deleted_at = null, updated_at = now()
    returning id into v_row_id;

    return v_row_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_upsert_master_tempo_batch(p_rows jsonb)
 RETURNS TABLE(idx integer, error_message text)
 LANGUAGE plpgsql
AS $function$
declare
    r jsonb;
    i integer := 0;
    v_count integer;
    v_clean text;
begin
    for r in select * from jsonb_array_elements(p_rows) loop
        i := i + 1;
        begin
            v_clean := nullif(trim(r->>'tempo_id'), '');

            update tracks_master
            set tempo_id = v_clean,
                estado_bo = case when v_clean is not null then 'ok'::estado_bo_enum else estado_bo end
            where lower(track_artist_concat) = lower(trim(r->>'track_artist'))
              and deleted_at is null;

            get diagnostics v_count = row_count;

            if v_count = 0 then
                idx := i;
                error_message := 'No se encontró la obra "' || (r->>'track_artist') || '" en la tabla principal.';
            else
                perform fn_merge_tempo_duplicates(v_clean);
                idx := i; error_message := null;
            end if;
            return next;
        exception when others then
            idx := i; error_message := sqlerrm;
            return next;
        end;
    end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_upsert_ranking_batch(p_rows jsonb, p_platform text)
 RETURNS TABLE(idx integer, track_created boolean, error_message text)
 LANGUAGE plpgsql
AS $function$
declare r jsonb; i integer := 0; v_result record;
begin
    for r in select * from jsonb_array_elements(p_rows) loop
        i := i + 1;
        begin
            select * into v_result from fn_upsert_ranking_row(
                r->>'track_name', r->>'artist_names', (r->>'pais_code')::pais_code_enum,
                fn_safe_int(r->>'rank'), fn_safe_int(r->>'peak_rank'), fn_safe_int(r->>'previous_rank'),
                fn_safe_int(r->>'weeks_on_chart'), fn_safe_bigint(r->>'streams'),
                r->>'source', r->>'uri', p_platform, fn_safe_numeric(r->>'weekly_growth'),
                coalesce(nullif(r->>'snapshot_date','')::date, current_date)
            );
            idx := i; track_created := v_result.track_created; error_message := null;
            return next;
        exception when others then
            idx := i; track_created := false; error_message := sqlerrm;
            return next;
        end;
    end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_upsert_tempo_report_batch(p_rows jsonb)
 RETURNS TABLE(idx integer, error_message text)
 LANGUAGE plpgsql
AS $function$
declare r jsonb; i integer := 0;
begin
    for r in select * from jsonb_array_elements(p_rows) loop
        i := i + 1;
        begin
            perform fn_upsert_tempo_report_row(
                r->>'tempo_id',
                (r->>'pais_code')::pais_code_enum,
                nullif(r->>'created_date','')::date,
                fn_safe_numeric(r->>'perf_pc'),
                fn_safe_numeric(r->>'mech_pc'),
                fn_safe_numeric(r->>'sync_pc'),
                r->>'publishers',
                r->>'contratos',
                r->>'estado_obra',
                r->>'song_title',
                nullif(trim(r->>'perf_pc'), ''),
                nullif(trim(r->>'mech_pc'), ''),
                nullif(trim(r->>'sync_pc'), ''),
                nullif(trim(r->>'originating_office'), '')
            );
            idx := i; error_message := null;
            return next;
        exception when others then
            idx := i; error_message := sqlerrm;
            return next;
        end;
    end loop;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_upsert_tempo_report_row(p_tempo_id text, p_pais_code pais_code_enum, p_created_date date, p_perf_pc numeric, p_mech_pc numeric, p_sync_pc numeric, p_publishers text, p_contratos text, p_estado_obra text, p_song_title text, p_perf_raw text, p_mech_raw text, p_sync_raw text, p_originating_office text)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare
    v_master_id uuid;
    v_tempo_id  text;
    v_row_id    uuid;
begin
    select tm.id, tm.tempo_id into v_master_id, v_tempo_id
    from tracks_master tm
    where fn_norm_tempo_id(tm.tempo_id) = fn_norm_tempo_id(p_tempo_id)
      and tm.deleted_at is null
    limit 1;

    if v_master_id is null then
        raise exception 'tempo_id % no existe en la tabla principal.', p_tempo_id;
    end if;

    insert into territory_tempo_report (
        track_master_id, tempo_id, pais_code, created_date, perf_pc, mech_pc, sync_pc,
        publishers, contratos, estado_obra, song_title, perf_raw, mech_raw, sync_raw,
        originating_office
    ) values (
        v_master_id, v_tempo_id, p_pais_code, p_created_date, p_perf_pc, p_mech_pc, p_sync_pc,
        p_publishers, p_contratos, p_estado_obra, p_song_title, p_perf_raw, p_mech_raw, p_sync_raw,
        p_originating_office
    )
    on conflict (tempo_id, pais_code)
    do update set
        created_date = excluded.created_date,
        perf_pc = excluded.perf_pc, mech_pc = excluded.mech_pc, sync_pc = excluded.sync_pc,
        publishers = excluded.publishers, contratos = excluded.contratos,
        estado_obra = excluded.estado_obra, song_title = excluded.song_title,
        perf_raw = excluded.perf_raw, mech_raw = excluded.mech_raw, sync_raw = excluded.sync_raw,
        originating_office = excluded.originating_office,
        deleted_at = null, updated_at = now()
    returning id into v_row_id;

    return v_row_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.fn_upsert_tempo_report_row(p_tempo_id text, p_pais_code pais_code_enum, p_created_date date, p_perf_pc numeric, p_mech_pc numeric, p_sync_pc numeric, p_publishers text, p_contratos text, p_estado_obra text, p_song_title text)
