CREATE OR REPLACE FUNCTION public.fn_upsert_territory_track(p_tempo_id text, p_pais_code pais_code_enum, p_percent_ctrl numeric, p_collect_mec numeric, p_collect_ejec numeric, p_society_id text)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_master_id UUID;
    v_row_id    UUID;
BEGIN
    SELECT id INTO v_master_id FROM tracks_master
    WHERE tempo_id = p_tempo_id AND deleted_at IS NULL;

    IF v_master_id IS NULL THEN
        RAISE EXCEPTION 'tempo_id % no existe en tracks_master. Debe cargarse primero en la tabla general.', p_tempo_id;
    END IF;

    INSERT INTO territory_tracks (track_master_id, tempo_id, pais_code, percent_ctrl, collect_mec, collect_ejec, society_id)
    VALUES (v_master_id, p_tempo_id, p_pais_code, p_percent_ctrl, p_collect_mec, p_collect_ejec, p_society_id)
    ON CONFLICT (tempo_id, pais_code)
    DO UPDATE SET
        percent_ctrl = EXCLUDED.percent_ctrl,
        collect_mec  = EXCLUDED.collect_mec,
        collect_ejec = EXCLUDED.collect_ejec,
        society_id   = EXCLUDED.society_id,
        deleted_at   = NULL,
        updated_at   = now()
    RETURNING id INTO v_row_id;

    RETURN v_row_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_bo_report_auto_revisar()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    v_mech_tempo numeric;
    v_oficina    text;
begin
    if new.estado_trabajo is null
       or new.estado_trabajo in ('REVISAR','OK BO-Tempo','OK - Obra AR','OK - Obra MX') then

        select tr.mech_pc, upper(unaccent(trim(coalesce(tr.originating_office, ''))))
          into v_mech_tempo, v_oficina
        from territory_tempo_report tr
        where tr.track_master_id = new.track_master_id
          and tr.pais_code = new.pais_code
          and tr.deleted_at is null;

        if v_mech_tempo is not null and new.mech_bo is not null then
            if abs(v_mech_tempo - new.mech_bo) <= 0.1 then
                new.estado_trabajo := 'OK BO-Tempo';

            -- Excepción: BO informa 0% pero Tempo tiene porcentaje, y la
            -- obra se originó en Argentina o México.
            elsif new.mech_bo = 0 and v_mech_tempo <> 0 and v_oficina like '%ARGENTINA%' then
                new.estado_trabajo := 'OK - Obra AR';
            elsif new.mech_bo = 0 and v_mech_tempo <> 0 and v_oficina like '%MEXICO%' then
                new.estado_trabajo := 'OK - Obra MX';

            else
                new.estado_trabajo := 'REVISAR';
            end if;
        else
            new.estado_trabajo := null;
        end if;
    end if;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_prevent_hard_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if current_setting('app.allow_hard_delete', true) is distinct from 'true' then
        raise exception 'DELETE físico no permitido en % (id=%). Use soft delete.', tg_table_name, old.id;
    end if;
    return old;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    new.updated_at := now();
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_sync_tempo_id_to_territory()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if new.tempo_id is distinct from old.tempo_id then
        update territory_tracks set tempo_id = new.tempo_id, updated_at = now()
        where track_master_id = new.id;
        update territory_control set tempo_id = new.tempo_id, updated_at = now()
        where track_master_id = new.id;
    end if;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_tempo_report_touch_bo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    update territory_bo_report
    set updated_at = now()
    where track_master_id = new.track_master_id
      and pais_code = new.pais_code;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_tracks_master_flag_duplicate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if exists (
        select 1 from tracks_master
        where lower(track_name_clean) = lower(new.track_name_clean)
          and lower(artist_name_clean) = lower(new.artist_name_clean)
          and deleted_at is null
          and id <> new.id
    ) then
        new.estado_bo := 'duplicada';
    end if;
    return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.trg_tracks_master_normalize()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    new.track_name_clean    := fn_normalize_text(new.track_name_raw);
    new.artist_name_clean   := fn_normalize_text(new.artist_name_raw);
    new.track_artist_concat := new.track_name_clean || ' - ' || new.artist_name_clean;
    new.updated_at          := now();
    return new;
end;
$function$
;
